package com.meterly.billing.run;

import com.meterly.billing.invoice.InvoiceDetail;
import java.util.Objects;

/**
 * Outcome of a billing run for one tenant and period. Sealed, so every caller handles both cases with an
 * exhaustive {@code switch} (the API maps them to 201 / 200, the scheduler to its counters).
 */
public sealed interface BillingRunResult {

    InvoiceDetail invoice();

    /** The invoice was generated by this run. */
    record Created(InvoiceDetail invoice) implements BillingRunResult {
        public Created {
            Objects.requireNonNull(invoice, "invoice");
        }
    }

    /** The period was already invoiced; the existing invoice is returned unchanged (idempotent re-run). */
    record AlreadyInvoiced(InvoiceDetail invoice) implements BillingRunResult {
        public AlreadyInvoiced {
            Objects.requireNonNull(invoice, "invoice");
        }
    }
}
